mapper.select:
SELECT r.*, l.apply_no AS applyNo, u.user_name AS userName FROM repay_record r LEFT JOIN loan_apply l ON l.loan_id = r.loan_id LEFT JOIN `user` u ON u.user_id = l.user_id
AND l.user_id = #{userId}
AND l.apply_no LIKE CONCAT('%', #{applyNo}, '%')
AND r.repay_no LIKE CONCAT('%', #{repayNo}, '%')
AND r.repay_status = #{repayStatus}
ORDER BY r.repay_id ASC
